"""Tests for the GPT-4o suspicious-description helper (OpenAI API mocked)."""

import os
import sys
import unittest
from unittest.mock import patch, MagicMock

sys.path.insert(
    0, os.path.join(os.path.dirname(__file__), "..", "transaction-service")
)
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

from transaction_service.verification.fraud_detector import (  # noqa: E402
    is_suspicious_description,
)


def _mock_response(content: str, status_code: int = 200):
    resp = MagicMock()
    resp.status_code = status_code
    resp.raise_for_status.return_value = None
    resp.json.return_value = {"choices": [{"message": {"content": content}}]}
    return resp


class TestIsSuspiciousDescription(unittest.TestCase):
    @patch.dict(os.environ, {"OPENAI_API_KEY": "test-key"})
    @patch("transaction_service.verification.fraud_detector.requests.post")
    def test_returns_true_for_suspicious(self, mock_post):
        mock_post.return_value = _mock_response("true")
        self.assertTrue(is_suspicious_description("send gift cards to this address"))

    @patch.dict(os.environ, {"OPENAI_API_KEY": "test-key"})
    @patch("transaction_service.verification.fraud_detector.requests.post")
    def test_returns_false_for_normal(self, mock_post):
        mock_post.return_value = _mock_response("false")
        self.assertFalse(is_suspicious_description("Coffee at the campus cafe"))

    @patch.dict(os.environ, {"OPENAI_API_KEY": "test-key"})
    @patch("transaction_service.verification.fraud_detector.requests.post")
    def test_uses_env_api_key(self, mock_post):
        mock_post.return_value = _mock_response("false")
        is_suspicious_description("lunch")
        _, kwargs = mock_post.call_args
        self.assertEqual(
            kwargs["headers"]["Authorization"], "Bearer test-key"
        )

    @patch.dict(os.environ, {}, clear=True)
    def test_missing_api_key_raises(self):
        with self.assertRaises(ValueError):
            is_suspicious_description("lunch")

    def test_empty_description_raises(self):
        with self.assertRaises(ValueError):
            is_suspicious_description("   ")


if __name__ == "__main__":
    unittest.main()
